command:
$ErrorActionPreference = 'Stop'
$branch = 'issue-502-quality-retry-merge'
$expectedHead = '4a54152636f5a9111c79334a3f5e82fe8d5d5137'
function Invoke-Git([string[]]$GitArgs) {
  Write-Host "git $($GitArgs -join ' ')"
  $output = & git @GitArgs
  $code = $LASTEXITCODE
  if ($output) { $output | Out-Host }
  if ($code -ne 0) { throw "git failed with exit $code`: git $($GitArgs -join ' ')" }
}
Invoke-Git @('fetch', '--no-tags', 'origin', "refs/heads/$branch`:refs/remotes/origin/$branch")
$remoteHead = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read remote branch head.' }
if ($remoteHead -ne $expectedHead) { throw "PR head drifted: expected $expectedHead got $remoteHead" }
$worktree = Join-Path $env:RUNNER_TEMP 'issue502_pr503_focused_validation'
if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
Invoke-Git @('worktree', 'prune')
Invoke-Git @('worktree', 'add', '--detach', $worktree, $remoteHead)
try {
  Push-Location $worktree
  $env:PYTHONDONTWRITEBYTECODE = '1'
  python -m py_compile .github/dcoir_review/scripts/dcoir_review/hardened/part_05_debug_and_merge.py .github/dcoir_review/scripts/dcoir_review/pareto_context/part_05a_hybrid_review.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v22.py .github/dcoir_review/scripts/openrouter_pr_review_quality_recovery_selftest.py
  if ($LASTEXITCODE -ne 0) { throw 'Python syntax validation failed.' }
  $tests = @(
    '.github/dcoir_review/scripts/openrouter_pr_review_quality_recovery_selftest.py',
    '.github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v22_selftest.py',
    '.github/dcoir_review/scripts/openrouter_pr_review_hardened_selftest.py',
    '.github/dcoir_review/scripts/openrouter_pr_review_pareto_context_selftest.py',
    '.github/dcoir_review/scripts/dcoir_review_semantic_recall_corpus_selftest.py',
    '.github/dcoir_review/scripts/dcoir_review_precision_regression_selftest.py'
  )
  foreach ($test in $tests) {
    Write-Host "RUN $test"
    python $test
    if ($LASTEXITCODE -ne 0) { throw "Selftest failed: $test" }
  }
  Invoke-Git @('diff', '--check', 'HEAD^', 'HEAD')
  $status = @(& git status --porcelain)
  if ($status.Count -ne 0) { throw "Detached validation worktree is not clean: $($status -join '; ')" }
  $validated = (& git rev-parse HEAD).Trim()
  if ($validated -ne $expectedHead) { throw "Validated wrong head: $validated" }
  Write-Host "ISSUE502_PR503_FOCUSED_VALIDATION=PASS:$validated"
} finally {
  Pop-Location -ErrorAction SilentlyContinue
  & git worktree remove --force $worktree 2>$null
  & git worktree prune 2>$null
}
